BK='.links_backup_20261028'
rd=lambda p: open(p,'rb').read()
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    for f in C: shutil.copyfile(os.path.join(BK,f.replace('/','_')),f)
    print('UNDONE: the seven pages are restored. Click Republish.'); sys.exit()
if all(os.path.exists(f) and b'class="fp-more"' in rd(f) for f in C):
    print('Already done. Nothing to change.'); sys.exit()
bad=[]
for f,v in C.items():
    if not os.path.exists(f): bad.append(f+' (not found)'); continue
    b=rd(f)
    if b.count(v['anchor'].encode())!=1: bad.append(f+' (the place to add the links was not found exactly once)')
    if b'class="fp-more"' in b: bad.append(f+' (already has the link list)')
    if b.count(b'<!DOCTYPE')!=1: bad.append(f+' (not exactly one DOCTYPE)')
if bad:
    print('STOP. Nothing was changed:'); print('\n'.join(bad)); sys.exit(1)
os.makedirs(BK,exist_ok=True)
for f,v in C.items():
    shutil.copyfile(f,os.path.join(BK,f.replace('/','_')))
    a=v['anchor'].encode(); b=rd(f)
    open(f,'wb').write(b.replace(a,v['block'].encode()+a,1))
ok=all(rd(f).count(b'class="fp-more"')==1 and rd(f).count(b'<!DOCTYPE')==1 for f in C)
print('DONE: link lists added to 7 pages. Click Republish.' if ok else 'CHECK FAILED. Run: python3 links_oct28.py --undo')
